            function is_channel_or_his_parent_collapsed(channel_id)
            {
                let result = false;
                let channel_index = get_channel_index_in_array_by_channel_id(channel_list, channel_id);

                if (channel_index == -1)
                {
                    return false;
                }

                if (channel_list[channel_index].is_channel_directly_collapsed == false)
                {
                    result = is_channel_or_his_parent_collapsed(channel_list[channel_index].parent_channel_id);
                }
                else
                {
                    result = true;
                }
                return result;
            }

